import { Component, OnDestroy, OnInit } from '@angular/core';
import { HistoryService } from '../history.service';
import { Subscription } from 'rxjs';
import { Message } from 'primeng/api';
import { FormBuilder } from '@angular/forms';
import { PrintService } from 'src/app/print.service';
import { AuxiliaryService } from 'src/app/accounting/auxiliary.service';
import { AuxiliaryAccount } from 'src/app/core/interfaces/accounts.interface';
import { DecimalService } from 'src/app/_services/decimal.service';
import { EditReturnService } from '../edit-return/edit-return.service';

@Component({
    selector: 'app-return-history',
    templateUrl: './return-history.component.html',
    styleUrl: './return-history.component.scss',
})
export class ReturnHistoryComponent implements OnInit, OnDestroy {
    constructor(
        private historyService: HistoryService,
        private fb: FormBuilder,
        private printService: PrintService,
        private auxiliaryService: AuxiliaryService,
        private decimalService: DecimalService,
        private editReturnService: EditReturnService,
    ) {}

    noInvoiceMessage: Message[];
    subscriptions = new Subscription();
    returnHistory;
    loading: boolean;
    selectedInvoice;
    selectedDate;
    items = [];
    customers: AuxiliaryAccount[];
    detailsDialogVisible: boolean;
    editReturnDialogVisible: boolean;

    invoiceToPrint;

    printable: boolean;

    selectedInvoiceTotals = {
        totalQty: 0,
        totalPrice: 0,
    };

    ngOnInit(): void {
        this.noInvoiceMessage = [
            { severity: 'info', detail: 'No selected invoice yet!' },
        ];

        this.subscriptions.add(
            this.historyService.returnHistory.subscribe((res) => {
                this.returnHistory = res;
            }),
        );
        this.subscriptions.add(
            this.historyService.loading.subscribe((res) => {
                this.loading = res;
            }),
        );
        this.subscriptions.add(
            this.historyService.detailsDialogVisible.subscribe((res) => {
                this.detailsDialogVisible = res;
            }),
        );
        this.subscriptions.add(
            this.auxiliaryService.customers.subscribe((res) => {
                this.customers = res;
            }),
        );
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    // search form builder
    searchForm = this.fb.group({
        invoice_number: [null],
        customer_id: [null],
        invoice_date: [null],
    });

    submitSearch() {
        console.log(this.searchForm.value);
        this.historyService.fetchReturnHistory(this.searchForm.value as any);
    }

    resetSearch() {
        this.searchForm.reset();
        this.historyService.fetchReturnHistory(null);
    }

    // preview invoice details
    showInvoiceDialog(invoice) {
        this.items = invoice.invoice_map;
        this.items.forEach((element) => {
            this.selectedInvoiceTotals.totalQty += element.quantity;
            this.selectedInvoiceTotals.totalPrice = this.decimalService.add(
                this.selectedInvoiceTotals.totalPrice,
                element.total_price,
            );
        });
        this.historyService.detailsDialogVisible.next(true);
    }

    // close dialog
    hideInvoiceDialog() {
        this.historyService.detailsDialogVisible.next(false);
        this.selectedInvoiceTotals = {
            totalQty: 0,
            totalPrice: 0,
        };
    }

    // Edit Invoice
    openEditDialog(data) {
        this.historyService.editReturnDialogVisible.set(true);
        // this.edit
        this.editReturnService.order_id = data.order_id;
        this.editReturnService.invoice_number =
            data.invoice_number.substring(3);

        this.editReturnService.invoice_items.next(data.invoice_map);
        this.editReturnService.customer_id.next(data.customer_id);
        this.editReturnService.include_vat =
            data.include_vat == 1 ? true : false;
        this.editReturnService.discount_percent = data.discount_percent;
        this.editReturnService.discount_percent_on_total =
            data.discount2_percent;
        this.editReturnService.invoice_date = data.order_datetime;
        this.editReturnService.calculateTotal();
        this.editReturnService.link_id = data.link_id;
    }

    closeEditDialog() {
        this.historyService.editReturnDialogVisible.set(false);
        this.editReturnService.invoice_items.next(null);
    }

    // PRINT INVOICE
    print(invoice) {
        this.printService.print(invoice, 'return');
    }
}
