import { Component, inject, ViewChild } from '@angular/core';
import { HistoryService } from '../history.service';
import { Subscription } from 'rxjs';
import { ConfirmationService, Message } from 'primeng/api';
import { FormBuilder } from '@angular/forms';
import { PrintService } from 'src/app/print.service';
import { AuxiliaryService } from 'src/app/accounting/auxiliary.service';
import { AuxiliaryAccount } from 'src/app/core/interfaces/accounts.interface';
import { DecimalService } from 'src/app/_services/decimal.service';
import { EditOrderService } from '../edit-order/edit-order.service';
import { UserService } from 'src/app/_services/user.service';
import { jsPDF } from 'jspdf';
import { CurrencyPipe } from '@angular/common';
import autoTable from 'jspdf-autotable';

@Component({
    selector: 'app-order-history',
    templateUrl: './order-history.component.html',
    styleUrl: './order-history.component.scss',
})
export class OrderHistoryComponent {
    readonly confirmationService = inject(ConfirmationService);
    constructor(
        private historyService: HistoryService,
        private fb: FormBuilder,
        private auxiliaryService: AuxiliaryService,
        private decimalService: DecimalService,
        private editOrderService: EditOrderService
    ) {}

    readonly currencyPipe = inject(CurrencyPipe);

    readonly userService = inject(UserService);
    userType = this.userService.userType;

    noInvoiceMessage: Message[];
    subscriptions = new Subscription();
    ordersHistory = this.historyService.ordersHistory;
    loading: boolean;
    selectedInvoice?;
    selectedDate;
    items = [];
    customers: AuxiliaryAccount[];
    detailsDialogVisible: boolean;

    selectedInvoiceTotals = {
        totalQty: 0,
        totalPrice: 0,
    };

    ngOnInit(): void {
        this.noInvoiceMessage = [
            { severity: 'info', detail: 'No selected invoice yet!' },
        ];
        this.subscriptions.add(
            this.historyService.loading.subscribe((res) => {
                this.loading = res;
            })
        );
        this.subscriptions.add(
            this.historyService.detailsDialogVisible.subscribe((res) => {
                this.detailsDialogVisible = res;
            })
        );
        this.subscriptions.add(
            this.auxiliaryService.customers.subscribe((res) => {
                this.customers = res;
            })
        );
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    // search form builder
    searchForm = this.fb.group({
        customer_id: [null],
        invoice_date: [null],
    });

    submitSearch() {
        this.historyService.fetchOrdersHistory(this.searchForm.value as any);
    }

    resetSearch() {
        this.searchForm.reset();
        this.historyService.fetchOrdersHistory(null);
    }

    // preview invoice details
    showInvoiceDialog(invoice) {
        this.items = invoice.invoice_map;
        this.items.forEach((element) => {
            this.selectedInvoiceTotals.totalQty += element.quantity;
            this.selectedInvoiceTotals.totalPrice = this.decimalService.add(
                this.selectedInvoiceTotals.totalPrice,
                element.total_price
            );
        });
        this.historyService.detailsDialogVisible.next(true);
    }

    // close dialog
    hideInvoiceDialog() {
        this.historyService.detailsDialogVisible.next(false);
        this.selectedInvoiceTotals = {
            totalQty: 0,
            totalPrice: 0,
        };
    }

    // Edit Invoice
    openEditDialog(data) {
        this.historyService.editOrdersDialogVisible.set(true);
        // this.edit
        this.editOrderService.order_id = data.order_id;

        this.editOrderService.invoice_items.next(data.invoice_map);
        this.editOrderService.customer_id.next(data.customer_id);
        this.editOrderService.include_vat =
            data.include_vat == 1 ? true : false;
        this.editOrderService.discount_percent = data.discount_percent;
        this.editOrderService.discount_percent_on_total =
            data.discount2_percent;
        this.editOrderService.invoice_date = data.order_datetime;
        this.editOrderService.order_notes = data.order_notes;

        this.editOrderService.calculateTotal();
    }

    closeEditDialog() {
        this.historyService.editOrdersDialogVisible.set(false);
        this.editOrderService.invoice_items.next(null);
    }

    completeOrder(data) {
        this.confirmationService.confirm({
            key: 'home',
            message: `Are you sure that you want to delete invoice"?`,
            header: 'Warning',
            icon: 'pi pi-exclamation-triangle',
            acceptButtonStyleClass: 'p-button-danger',
            rejectButtonStyleClass: 'p-button-secondary',
            defaultFocus: 'reject',
            accept: () => {
                this.historyService.completeOrder(data);
            },
        });
    }

    // export PDF

    formatCurrency(value: string | number): string {
        return (
            this.currencyPipe.transform(value, 'USD', 'symbol', '1.2-2') || ''
        );
    }

    exportPDF(invoice) {
        console.log(invoice);
        const doc = new jsPDF();
        const pageWidth = doc.internal.pageSize.width; // Get page width

        doc.setFontSize(14);
        const title = `Order Note`;
        const textWidth = doc.getTextWidth(title);
        doc.text(title, (pageWidth - textWidth) / 2, 10);

        doc.setFontSize(10);
        doc.text(`${invoice.customer_name}`, 10, 20);

        doc.setFontSize(9);

        doc.text(`Generated on: ${invoice.order_datetime}`, 150, 30);

        const cols = ['SKU', 'Description', 'Unit Price', 'Qty', 'Total Price'];

        const items = invoice.invoice_map;

        const rows = items.map((record, index) => [
            record.sku || '---',
            record.product_name,
            this.formatCurrency(record.unit_price),
            record.quantity,
            this.formatCurrency(record.total_price),
        ]);

        autoTable(doc, {
            startY: 40,
            head: [cols],
            body: rows,
            // foot: [footer],
            styles: {
                halign: 'center',
                fontSize: 8,
            },
            headStyles: {
                fillColor: 'F9FAFB',
                textColor: '#4B5563',
            },
            footStyles: {
                fillColor: 'F9FAFB',
                textColor: '#4B5563',
            },
        });

        // Total at the end
        // const total = items.reduce(
        //     (sum, item) => sum + item.qty * item.price,
        //     0
        // );

        // doc.text(`Generated on: ${invoice.order_datetime}`, 150, 30);
        doc.setFontSize(10);
        const finalY = (doc as any).lastAutoTable.finalY || 20;
        doc.text(
            `Subtotal: ${this.formatCurrency(invoice.sub_total)}`,
            170,
            finalY + 10
        );

        doc.text(
            `Discount: ${this.formatCurrency(invoice.discount_value)}`,
            170,
            finalY + 15
        );

        const netTotal = invoice.sub_total - invoice.discount_value;
        doc.text(`Net: ${this.formatCurrency(netTotal)}`, 170, finalY + 20);

        if (invoice.discount2_percent) {
            doc.text(
                `Discount 2: ${this.formatCurrency(invoice.discount2_value)}`,
                170,
                finalY + 25
            );

            const netTotal2 = netTotal - invoice.discount2_value;
            doc.text(
                `Subtotal 2: ${this.formatCurrency(netTotal2)}`,
                170,
                finalY + 30
            );
        }

        if (invoice.include_vat) {
            const vatText = `Vat $: ${this.formatCurrency(invoice.vat_value)}`;
            doc.text(vatText, 170, finalY + 35);

            const vatTextWidth = doc.getTextWidth(vatText);
            doc.text(
                `Vat LBP: ${invoice.vat_value_lbp.toLocaleString()} L.L`,
                pageWidth - vatTextWidth - 30,
                finalY + 35
            );
        }

        doc.text(
            `Grand Total: ${this.formatCurrency(invoice.total_amount)}`,
            170,
            finalY + 40
        );

        // Save PDF
        doc.save(`${invoice.customer_name}-order.pdf`);
    }
}
