import { Component, inject, OnDestroy, OnInit } from '@angular/core';
import { HistoryService } from '../history.service';
import { Subscription } from 'rxjs';
import { ConfirmationService, Message } from 'primeng/api';
import { FormBuilder } from '@angular/forms';
import { PrintService } from 'src/app/print.service';
import { AuxiliaryService } from 'src/app/accounting/auxiliary.service';
import { AuxiliaryAccount } from 'src/app/core/interfaces/accounts.interface';
import { DecimalService } from 'src/app/_services/decimal.service';
import { EditInvoiceService } from '../edit-invoice/edit-invoice.service';
import { LinksService } from 'src/app/components/links-component/links.service';

@Component({
    selector: 'app-sale-history',
    templateUrl: './sale-history.component.html',
    styleUrl: './sale-history.component.scss',
})
export class SaleHistoryComponent implements OnInit, OnDestroy {
    constructor(
        private historyService: HistoryService,
        private fb: FormBuilder,
        private printService: PrintService,
        private auxiliaryService: AuxiliaryService,
        private decimalService: DecimalService,
        private editInvoiceService: EditInvoiceService,
    ) {
        this.submitSearch();
    }

    readonly linksService = inject(LinksService);

    links = this.linksService.links;
    loadingLinks = this.linksService.loadingLinks;

    noInvoiceMessage: Message[];
    subscriptions = new Subscription();
    salesHistory;
    loading: boolean;
    selectedInvoice;
    selectedDate;
    items = [];
    customers: AuxiliaryAccount[];
    detailsDialogVisible: boolean;
    editDialogVisible: boolean;

    invoiceToPrint;

    printable: boolean;

    selectedInvoiceTotals = {
        totalQty: 0,
        totalPrice: 0,
    };

    ngOnInit(): void {
        this.noInvoiceMessage = [
            { severity: 'info', detail: 'No selected invoice yet!' },
        ];

        this.subscriptions.add(
            this.historyService.salesHistory.subscribe((res) => {
                this.salesHistory = res;
            }),
        );
        this.subscriptions.add(
            this.historyService.loading.subscribe((res) => {
                this.loading = res;
            }),
        );
        this.subscriptions.add(
            this.historyService.detailsDialogVisible.subscribe((res) => {
                this.detailsDialogVisible = res;
            }),
        );
        this.subscriptions.add(
            this.historyService.editDialogVisible.subscribe((res) => {
                this.editDialogVisible = res;
            }),
        );
        this.subscriptions.add(
            this.auxiliaryService.customers.subscribe((res) => {
                this.customers = res;
            }),
        );
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    // search form builder
    searchForm = this.fb.group({
        invoice_number: [null],
        customer_id: [null],
        invoice_date: [null],
        link_id: [null],
        order_notes: [null],
    });

    submitSearch() {
        this.historyService.fetchSalesHistory(this.searchForm.value as any);
    }

    resetSearch() {
        this.searchForm.reset();
        this.historyService.fetchSalesHistory(null);
    }

    // preview invoice details
    showInvoiceDialog(invoice) {
        this.items = invoice.invoice_map;
        this.items.forEach((element) => {
            this.selectedInvoiceTotals.totalQty += element.quantity;
            this.selectedInvoiceTotals.totalPrice = this.decimalService.add(
                this.selectedInvoiceTotals.totalPrice,
                element.total_price,
            );
        });
        this.historyService.detailsDialogVisible.next(true);
    }

    // close dialog
    hideInvoiceDialog() {
        this.historyService.detailsDialogVisible.next(false);
        this.selectedInvoiceTotals = {
            totalQty: 0,
            totalPrice: 0,
        };
    }

    // Edit Invoice
    openEditDialog(data) {
        this.historyService.editDialogVisible.next(true);
        // this.edit
        this.editInvoiceService.order_id = data.order_id;
        this.editInvoiceService.invoice_number =
            data.invoice_number.substring(3);

        this.editInvoiceService.invoice_items.next(data.invoice_map);
        this.editInvoiceService.customer_id.next(data.customer_id);
        this.editInvoiceService.include_vat =
            data.include_vat == 1 ? true : false;
        this.editInvoiceService.discount_percent = data.discount_percent;
        this.editInvoiceService.discount_percent_on_total =
            data.discount2_percent;
        this.editInvoiceService.invoice_date = data.order_datetime;
        this.editInvoiceService.order_notes = data.order_notes;
        this.editInvoiceService.include_delivery =
            data.include_delivery == 1 ? true : false;
        this.editInvoiceService.delivery_charge = data.delivery_charge;
        this.editInvoiceService.link_id = data.link_id;
        this.editInvoiceService.calculateTotal();
    }

    closeEditDialog() {
        this.historyService.editDialogVisible.next(false);
        this.editInvoiceService.invoice_items.next(null);
    }

    // PRINT INVOICE
    print(invoice) {
        this.printService.print(invoice, 'sale');
    }

    printDelivery(invoice) {
        let totalQty = 0;
        invoice.invoice_map.forEach((element) => {
            totalQty += element.quantity;
        });
        invoice.totalQty = totalQty;
        this.printService.printDelivery(invoice);
    }
}
