import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { HistoryHomeComponent } from './history-home/history-home.component';
import { SaleHistoryComponent } from './sale-history/sale-history.component';
import { PaymentHistoryComponent } from './payment-history/payment-history.component';
import { PurchaseHistoryComponent } from './purchase-history/purchase-history.component';
import { ReturnHistoryComponent } from './return-history/return-history.component';
import { OrderHistoryComponent } from './order-history/order-history.component';

const routes: Routes = [
    {
        path: '',
        component: HistoryHomeComponent,
        children: [
            {
                path: 'sales-history',
                data: {
                    breadcrumb: 'Sales History',
                },
                component: SaleHistoryComponent,
            },
            {
                path: 'orders-history',
                data: {
                    breadcrumb: 'Orders History',
                },
                component: OrderHistoryComponent,
            },
            {
                path: 'return-history',
                data: {
                    breadcrumb: 'Return History',
                },
                component: ReturnHistoryComponent,
            },
            {
                path: 'purchases-history',
                data: {
                    breadcrumb: 'Purchases History',
                },
                component: PurchaseHistoryComponent,
            },
            { path: '**', redirectTo: '/history/invoice-history' },
        ],
    },
];

@NgModule({
    imports: [RouterModule.forChild(routes)],
    exports: [RouterModule],
})
export class HistoryRoutesModule {}
