import { Component, OnDestroy, OnInit } from '@angular/core';
import { HistoryService } from '../history.service';
import { Subscription } from 'rxjs';
import { ConfirmationService, Message } from 'primeng/api';
import { FormBuilder } from '@angular/forms';
import { AuxiliaryAccount } from 'src/app/core/interfaces/accounts.interface';
import { AuxiliaryService } from 'src/app/accounting/auxiliary.service';
import { EditPurchaseService } from '../edit-purchase/edit-purchase.service';

@Component({
    selector: 'app-purchase-history',
    templateUrl: './purchase-history.component.html',
    styleUrl: './purchase-history.component.scss',
})
export class PurchaseHistoryComponent {
    constructor(
        private historyService: HistoryService,
        private formBuilder: FormBuilder,
        private auxiliaryService: AuxiliaryService,
        private editPurchaseService: EditPurchaseService
    ) {}

    noInvoiceMessage: Message[];
    subscriptions = new Subscription();
    purchaseHistory;
    loading: boolean;
    selectedInvoice;
    selectedDate;
    items = [];
    suppliers: AuxiliaryAccount[];
    detailsDialogVisible: boolean;

    editDialogVisible: boolean = false;

    invoiceToPrint;

    printable: boolean = false;

    ngOnInit(): void {
        this.noInvoiceMessage = [
            { severity: 'info', detail: 'No selected invoice yet!' },
        ];

        this.subscriptions.add(
            this.historyService.purchasesHistory.subscribe((res) => {
                this.purchaseHistory = res;
            })
        );
        this.subscriptions.add(
            this.historyService.loading.subscribe((res) => {
                this.loading = res;
            })
        );

        this.subscriptions.add(
            this.historyService.detailsDialogVisible.subscribe((res) => {
                this.detailsDialogVisible = res;
            })
        );
        this.subscriptions.add(
            this.auxiliaryService.suppliers.subscribe((res) => {
                this.suppliers = res;
            })
        );
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    // search form builder
    searchForm = this.formBuilder.group({
        invoice_number: [null],
        supplier_id: [null],
        invoice_date: [null],
    });

    submitSearch() {
        this.historyService.fetchPurchasesHistory(this.searchForm.value as any);
    }

    resetSearch() {
        this.searchForm.reset();
        this.historyService.fetchPurchasesHistory(null);
    }
    // invoice selection
    // selectInvoice() {
    //     this.items = this.selectedInvoice['invoice_map'];
    // }

    // // // invoice unselection
    // unselectInvoice() {
    //     this.items = []
    // }

    // preview invoice details
    showInvoiceDialog(invoice) {
        this.items = invoice.invoice_map;
        this.historyService.detailsDialogVisible.next(true);
    }

    // close dialog
    hideInvoiceDialog() {
        this.historyService.detailsDialogVisible.next(false);
    }

    // edit dialog function
    openEditPurchaseDialog(record) {
        this.editPurchaseService.invoice.next(record.invoice_map);
        this.editPurchaseService.purchaseForm.next({
            order_id: record.order_id,
            partner_id_fk: record.partner_id_fk,
            journal_voucher_id: record.journal_voucher_id,
            order_datetime: record.order_datetime,
            subtotal: record.subtotal,
            total_weight: record.total_weight,
            costs_by_weight: record.costs_by_weight,
            costs_by_value: record.costs_by_value,
            have_vat: record.have_vat == 1 ? true : false,
            vat_amount: record.vat_amount,
            reference_number: record.reference_number,
            purchase_notes: record.purchase_notes,
        });
        this.editPurchaseService.calculateTotal();
        this.historyService.editPurchaseDialogVisible.set(true);
    }
}
